using Tern.App.Commands;
using Tern.App.Settings;

namespace Tern.App.Help;

public sealed record SettingFeature(string Property, string Name, string Category, string Description, string How)
{
    public string Id => "settings." + Property;
    public FeatureHelp Help => new(Id, Name, "Settings · " + SettingsNavigation.Title(Category), Description, "Available without a document. Settings affect Tern preferences, not the contents of saved documents.", "", CommandIds.Settings,
    ["Open Edit → Settings, or search Settings in the command palette. No document is required.", $"Choose {SettingsNavigation.Title(Category)} in the category navigation, or type {Name} in Find a setting.", How, "Choose Done to apply and save your preferences. Reopen Settings to adjust the value again."]);
}

public static partial class FeatureCatalog
{
    public static IReadOnlyList<SettingFeature> SettingsFeatures { get; } =
    [
        new(nameof(AppSettings.Theme), "Theme", "Appearance", "The saved default appearance used when Tern starts. Paper, Linen and Mist are light; Midnight, Graphite and Harbor are dark; System follows Windows. Apply updates open windows without changing documents.", "Choose a theme or System in Theme, then Apply. Cancel discards an unapplied appearance choice. The View menu updates the same saved preference."),
        new(nameof(AppSettings.EditorFontFamily), "Editor font", "Editor", "The source editor uses this font family. A comma-separated fallback list lets Windows choose an available typeface.", "Enter an installed font family such as Cascadia Code. Leave the field to accept it; a blank name is ignored."),
        new(nameof(AppSettings.EditorFontSize), "Editor font size", "Editor", "Set the source text size from 8 to 48. Preview text has a separate size.", "Use the number field or its arrows to choose a source editor text size from 8 to 48."),
        new(nameof(AppSettings.PreviewFontSize), "Preview font size", "Reading", "Set rendered document text size from 8 to 48 without changing the saved Markdown.", "Choose a preview text size from 8 to 48. Source text size remains independent."),
        new(nameof(AppSettings.PreviewFontFamily), "Reading font", "Reading", "Choose the font family for prose in Reading and Split preview. Source, code blocks, math and exported PDF fonts remain independent. This changes appearance only.", "Choose an installed font or enter a comma-separated fallback list, then Apply. The reading sample previews the choice; reset restores the standard reading font stack."),
        new(nameof(AppSettings.PreviewFullWidth), "Use full preview width", "Reading", "Use the available preview pane width instead of centering a narrow text column. Enabled by default. Turn it off to use the Reading width limit.", "Enable Use full preview width to fill the pane with readable content and small padding. Disable it if you prefer a centered column, then adjust Reading width."),
        new(nameof(AppSettings.ReadingWidth), "Reading width", "Reading", "When Use full preview width is off, limit the centered text column from 360 to 1,600 device-independent units. This changes layout, not the Markdown or font size.", "Turn off Use full preview width, then choose a width from 360 to 1,600. Turn full width back on to use the whole pane again."),
        new(nameof(AppSettings.UiScale), "Interface text scale", "Appearance", "Scale application text up to 250%, with a minimum that keeps captions at least 11 pixels. Use 1 for 100%, 1.25 for 125%, or 1.5 for 150%. This is separate from Windows DPI scaling and the document editor/preview font sizes; headings keep their visual hierarchy.", "Choose a text scale from approximately 0.917 to 2.5 and choose Apply. Open dialogs update too. Editor font size and Preview font size control document text separately; return this value to 1 for the default interface body text."),
        new(nameof(AppSettings.ScaleDocumentText), "Also scale editor and preview text", "Appearance", "Multiply the source editor and preview text sizes by the Interface text scale so documents grow with the rest of the interface. Off by default; the saved font sizes are not changed.", "Choose an Interface text scale above 1, check Also scale editor and preview text, then Apply. Uncheck it to size document text only by the Editor and Preview font sizes."),
        new(nameof(AppSettings.ReduceMotion), "Reduce motion", "Appearance", "Request reduced interface motion for a calmer experience. Progress bars without a measured amount stop moving and show an elapsed-time counter instead. This does not change document content.", "Check Reduce motion to request fewer interface animations; uncheck it to use the standard behavior."),
        new(nameof(AppSettings.ShowContextGuidance), "Show next-step guidance", "Layout", "Show the dismissible contextual help strip below the writing area. Dismissal is remembered across restarts; dialog guidance stays available.", "Enable this preference and Apply to restore the main next-step strip, or choose Dismiss guidance on that strip to hide it."),
        new(nameof(AppSettings.WordWrap), "Wrap long lines", "Editor", "Display long source lines across multiple visual lines. Wrapping never inserts line breaks into your file.", "Check Wrap long lines to avoid horizontal scrolling. Uncheck it to keep each source line on one visual line."),
        new(nameof(AppSettings.ShowLineNumbers), "Show line numbers", "Editor", "Show source line numbers beside the text to help navigation and discussion.", "Check Show line numbers to display the source editor gutter; uncheck to hide its numbers."),
        new(nameof(AppSettings.HighlightCurrentLine), "Highlight current line", "Editor", "Use a subtle background to mark the source line containing the caret.", "Check Highlight current line, then return to the editor and move the caret to see the highlighted line."),
        new(nameof(AppSettings.ShowSpaces), "Show spaces in Source", "Editor", "Display a small marker for spaces in Source and the read-only Reference source. Markers are visual guides; saved Markdown is unchanged.", "Enable and Apply to inspect spacing. Disable to hide markers without deleting spaces."),
        new(nameof(AppSettings.ShowTabs), "Show tabs in Source", "Editor", "Display tab-character markers in Source and Reference. This distinguishes actual tabs from spaces without converting indentation.", "Enable and Apply to inspect tab characters. Tab size and Insert spaces when pressing Tab remain separate preferences."),
        new(nameof(AppSettings.ShowEndOfLine), "Show line-ending markers", "Editor", "Show the existing line terminators in Source and Reference. The markers do not add or convert CRLF, LF or CR characters.", "Enable and Apply to inspect line endings. Use the explicit File encoding and line-ending commands to convert a document when needed."),
        new(nameof(AppSettings.ShowColumnRuler), "Show Source column ruler", "Editor", "Draw a vertical guide in Source and Reference at the chosen column. It does not wrap lines or insert breaks.", "Enable and Apply, then choose Source ruler column. Disable the ruler to remove only the guide."),
        new(nameof(AppSettings.ColumnRulerPosition), "Source ruler column", "Editor", "Place the Source and Reference column guide from column 40 to 240. The initial position is 80.", "Choose a column and enable Show Source column ruler, then Apply. Text and saved bytes are unchanged."),
        new(nameof(AppSettings.EditorLineHeight), "Source line spacing", "Editor", "Set the Source and Reference line-height multiplier from 1 to 2. The initial multiplier is 1.16. This improves visual spacing without adding blank lines.", "Choose a multiplier, then Apply. Source font size is separate; Reading prose keeps its own typography."),
        new(nameof(AppSettings.AllowScrollBelowDocument), "Scroll below the last Source line", "Editor", "Allow empty scrolling space below the final Source and Reference line. Enabled by default; turning it off keeps scrolling bounded by the document.", "Enable or disable and Apply. This does not add blank lines to the file."),
        new(nameof(AppSettings.CutCopyWholeLine), "Copy or cut the current line without a selection", "Editor", "With no selected text, Copy or Cut uses the current Source line, including its terminator. Enabled by default. Cut remains undoable and only removes text after copying succeeds.", "Disable and Apply if Copy and Cut should require a selection. An explicit selection is always copied as selected; Reference remains read-only."),
        new(nameof(AppSettings.SpellCheckEnabled), "Windows spell checking", "Editor", "Underline misspelled prose using the installed Windows dictionary for your current language. Code, link destinations and front matter are excluded. Large documents are checked around the visible editor area.", "Right-click a marked word for suggestions. Corrections are undoable. Install language spelling support in Windows Settings if no dictionary is available. Nothing is sent online."),
        new(nameof(AppSettings.HybridSourceEnabled), "Hybrid Source display", "Editor", "Show local image thumbnails, task controls, scaled headings and dimmed writing marks outside the caret line. This changes presentation only; Markdown stays editable.", "Enable Hybrid Source display and Apply. Move the caret onto a decorated line to edit its original Markdown. Turn the option off to return to plain Source display."),
        new(nameof(AppSettings.DefaultEncoding), "Default encoding (new files)", "Files", "Used for documents created after Apply, including templates and new files in folders. UTF-8 is recommended. Existing and restored documents keep their own encoding; unrepresentable characters are never silently replaced.", "Choose an encoding, then Apply. UTF-16 and UTF-32 new files always include a byte-order mark for reliable reopening. For the current document, use File → Encoding and line endings instead."),
        new(nameof(AppSettings.DefaultEncodingHasBom), "Include a BOM in new files", "Files", "Optional for UTF-8 and off by default. UTF-16 and UTF-32 always include a BOM; other encodings cannot include one. This affects newly created documents only.", "With Default encoding set to UTF-8, select or clear this option and Apply. The option is fixed automatically for other encodings."),
        new(nameof(AppSettings.DefaultLineEnding), "Default line endings (new files)", "Files", "Choose CRLF, LF or CR for new blank documents, templates and newly created notes. Existing and restored text keeps its line endings.", "Choose the line endings for future documents, then Apply. Use File → Encoding and line endings → Change Line Endings to convert the current document explicitly."),
        new(nameof(AppSettings.AutoSaveEnabled), "Save real files after idle", "Files", "Off by default. Save writable, already-named dirty documents after the configured idle delay using normal conflict checks. This writes the actual file, unlike recovery checkpoints.", "Enable only if automatic real-file saves are wanted. Set Idle seconds before saving, then Apply. Untitled and read-only documents still need an explicit save. Resolve any conflict normally."),
        new(nameof(AppSettings.AutoSaveIdleSeconds), "Idle seconds before saving", "Files", "Wait 30 to 3,600 seconds after the last edit before saving a real file when idle saving is enabled. Failed or cancelled saves wait for another edit or an explicit Save.", "Choose an idle interval, enable Save real files after idle, and Apply. A new edit restarts the delay."),
        new(nameof(AppSettings.ExportPreferences), "Export defaults", "Files", "Review and edit remembered PDF and HTML options before the next export. Each format keeps its own options; export still asks for the output file. Plain text has no page or theme options.", "Choose PDF or HTML, set its available options, then Apply or Done. Reset selected format restores only that format's defaults. Forget export folders clears remembered destinations after Apply, without deleting files or bypassing the next destination picker."),
        new(nameof(AppSettings.TabSize), "Tab size", "Editor", "Choose an indentation width of 1 to 16 spaces. Existing tab characters are displayed at this width.", "Choose the number of spaces used for indentation. Insert spaces when pressing Tab controls whether new indentation uses spaces or tabs."),
        new(nameof(AppSettings.InsertSpacesForTab), "Insert spaces when pressing Tab", "Editor", "When enabled, Tab inserts spaces using Tab size. When disabled, it inserts a tab character.", "Choose spaces for consistent indentation across editors, or uncheck to insert literal tab characters. Existing text is not converted."),
        new(nameof(AppSettings.SyncScroll), "Synchronise scrolling in split view", "Reading", "Move source and preview together using source positions. Available in Split view; turn it off to scroll each pane independently.", "Check Synchronise scrolling in split view, choose Split, then scroll either pane. Uncheck for independent pane positions."),
        new(nameof(AppSettings.DefaultViewMode), "Default view", "Reading", "Choose the startup view: Source, Split or Reading. An open workspace can restore its own saved layout. Current view controls switch the active layout.", "Choose Source to edit Markdown, Split for source and preview, or Reading for the preview alone. This saved default is used at the next startup or when no workspace layout overrides it."),
        new(nameof(AppSettings.DefaultProfile), "Default profile (new files)", "Editor", "Choose the Markdown dialect used for new documents. CommonMark is conservative; GFM adds GitHub features; Extended enables additional supported syntax.", "Choose a Markdown profile for new files. This does not rewrite Markdown or convert existing files."),
        new(nameof(AppSettings.RestoreSession), "Restore tabs and folder on startup", "Files", "Reopen saved document paths and the workspace on the next startup. Unsaved-work recovery is a separate protection.", "Check to restore your saved-file tabs and folder at startup. Do not rely on the restore list as a backup of unsaved text."),
        new(nameof(AppSettings.AutoReloadCleanDocuments), "Reload unmodified files changed on disk", "Files", "Automatically reload external changes only when the open document has no unsaved edits. Conflicting edits still require a decision.", "Check to reload clean documents changed by another program. Leave it off when you prefer to review external changes yourself."),
        new(nameof(AppSettings.EnsureFinalNewlineOnSave), "Ensure a final newline when saving", "Files", "Add a line break at the end of a nonempty document when it is saved. Empty documents remain empty.", "Enable this only if your tools expect a final line break. The change is applied on a subsequent save."),
        new(nameof(AppSettings.TrimTrailingWhitespaceOnSave), "Trim trailing whitespace when saving", "Files", "Remove trailing spaces on save while preserving a deliberate pair used for a Markdown hard line break.", "Enable to tidy trailing whitespace on the next save. Review the resulting text if your document uses meaningful spacing."),
        new(nameof(AppSettings.AllowExternalLinkOpening), "Allow opening links in other applications (asks first)", "Privacy", "Permit a confirmation prompt before a link is opened in a browser or another application. Turning it off blocks external launches.", "Check to allow reviewed external links, or uncheck to prevent Tern from launching them. Opening a web link can use the network."),
        new(nameof(AppSettings.RemoteImages), "Remote images", "Privacy", "Ask blocks remote images until you approve a document. Always permits them; Never blocks them in preview, export and print. Loading an image contacts its host.", "Choose Ask, Always or Never, then Apply. Under Ask, use the document banner to Load once or Always for this file."),
        new(nameof(AppSettings.RemoteImageTrustedFiles), "Remembered remote-image approvals", "Privacy", "Forget every Always for this file approval saved on this device. This changes permissions for later requests and never deletes documents or images. Session-only approvals end when Tern closes.", "Choose Forget saved image approvals, then Apply. With Remote images set to Ask, restart Tern to end any existing session-only approvals too."),
        new(nameof(AppSettings.OfflineMode), "Offline mode", "Privacy", "Block remote images, URL import, AI, MCP and Copilot. Local editing and local resources remain available.", "Enable Offline mode here or use Offline in the status bar. Turn it off before explicitly connecting to a service."),
        new(nameof(AppSettings.KnowledgeAssistantEnabled), "Enable Explore your notes", "Knowledge assistant", "Enable AI answers from your workspace notes. Opening the window never contacts AI. Unfinished work returns to its last stage.", "Choose Edit → Explore your notes. Follow Ask, Check your notes, then Your answer. If no AI exists, Tern opens AI Connections first. Closing keeps unfinished work. Done finishes it; Ask a new question starts again. Normal workspaces keep a protected local checkpoint. Private workspaces keep tasks only while Tern is open."),
        new(nameof(AppSettings.KnowledgeAllowRemote), "Allow reviewed remote knowledge requests", "Knowledge assistant", "Off by default. Allow the notes you keep ticked to be sent to an online AI. Offline mode still blocks all AI.", "Enable here, or choose Yes, use online AI on the Check your notes screen. No note text is sent until you press Get my answer. Finding notes can share your question and possible notes' names and headings."),
        new(nameof(AppSettings.HistoryBudgetMiB), "Version history size (MiB)", "Files", "How much disk space saved versions may use for each document (1 to 1,024 MiB). Tern keeps up to 30 versions from the last hour, then one per hour for a day, one per day for 30 days, and one per week after that. History of a deleted file is kept for 30 days.", "Choose a size from 1 to 1,024 MiB. Lower values thin old versions sooner; the change applies the next time Tern starts."),
        new(nameof(AppSettings.SidebarVisible), "Show Library", "Layout", "Keep the Library sidebar visible, or hide it to give the document more horizontal room. View → Library offers the same choice while writing.", "Enable Show Library to keep folder and navigation controls visible. Disable it for a wider writing area; use View → Library to bring it back."),
        new(nameof(AppSettings.SidebarWidth), "Library width", "Layout", "Set the Library's preferred width from 180 to 800 device-independent units. You can also drag its divider while writing.", "Choose a width from 180 to 800, then Apply. Keep enough room for both the Library and your document panes."),
        new(nameof(AppSettings.InspectorVisible), "Show Inspector", "Layout", "Keep Outline, Links, Details and History visible beside your note. A compact window may temporarily hide the panel without changing this preference.", "Enable Show Inspector, then Apply. Use View → Inspector to restore it while writing."),
        new(nameof(AppSettings.InspectorWidth), "Inspector width", "Layout", "Set the Inspector's preferred width from 180 to 800 device-independent units. Drag its divider for a direct adjustment.", "Choose a width and Apply. Reset layout restores the standard pane widths without changing fonts or notes."),
        new(nameof(AppSettings.SourceShare), "Source pane share", "Layout", "Choose the fraction of Split view reserved for Source, from 0.15 to 0.85. Reading uses the remaining space.", "Choose 0.5 for equal panes, then Apply. Drag the pane divider to adjust the same preference while writing."),
        new(nameof(AppSettings.OnboardingDismissed), "Hide Tern Quick Start tips", "Layout", "Remember dismissal of the first-note welcome. Restored notes are never replaced by onboarding.", "Disable this preference to see the welcome on a future empty start. Help → Tern Quick Start opens it at any time without closing notes."),
        new(nameof(AppSettings.WorkspaceExclusions), "Workspace exclusion patterns", "Workspace", "Exclude workspace paths using one gitignore-style pattern per line. Patterns change scanning, not files; they take effect the next time a workspace opens. A .ternignore file is an alternative local to one workspace.", "Enter one reviewed pattern per line, such as drafts/. Choose Apply, then safely close and reopen the workspace to rescan with those rules. Remove a pattern to include the paths again."),
        new(nameof(AppSettings.SavedWorkspaceSearches), "Saved workspace searches", "Workspace", "Remember exact search queries separately for each workspace. Queries are shortcuts, not note copies; forgetting one keeps documents unchanged.", "Use Save search in workspace search to add a query to Library Shortcuts. Run or forget individual queries there. Resetting the Workspaces and search category forgets saved queries but does not delete notes."),
        new(nameof(AppSettings.FindMatchCase), "Match case in Find", "Workspace", "Use case-sensitive matching in the current-document Find and Replace bar. The bar's Match case control updates this same saved preference. Workspace full-text queries are separate.", "Enable and Apply to distinguish capital and lowercase text in in-note searches. Only the option is saved; Find and Replace text is not stored in Settings."),
        new(nameof(AppSettings.FindWholeWord), "Match whole words in Find", "Workspace", "Restrict current-document Find and Replace to complete words. The Find bar's Whole word control updates this same saved preference; workspace search is separate.", "Enable and Apply to avoid partial-word matches. Disabling broadens in-note matching. Search and replacement text is not saved."),
        new(nameof(AppSettings.FindUseRegex), "Use regular expressions in Find", "Workspace", "Interpret the current-document Find pattern as a regular expression. Off by default. The Find bar updates this same saved preference and still validates patterns and enforces its time limit.", "Enable only when using a regular expression. Apply refreshes an open Find bar with the selected options; review matches before replacing. No pattern or replacement text is stored in Settings."),
        new(nameof(AppSettings.TaskGroupByFile), "Group Library tasks by file", "Workspace", "Show a filename heading above each group in Library Tasks. Enabled by default. The Tasks view control updates this same saved preference; task completion and note text are unchanged.", "Enable or disable and Apply, or use Group by file in Library Tasks. Filtering and undoable task checkboxes continue to work independently."),
        new(nameof(AppSettings.KeyBindings), "Keyboard shortcut bindings", "Keyboard", "Configure command shortcuts in the Keyboard shortcuts category and recording editor. Current bindings, conflicts and defaults are shown there.", "Choose Edit keyboard shortcuts, select a command and Record keys. Assign applies the candidate; Clear recording cancels it. Close the shortcut editor, then choose Apply in Settings to persist the bindings."),
    ];

    public static IReadOnlyList<FeatureHelp> Subfeatures { get; } =
    [
        .. SettingsFeatures.Select(s => s.Help),
        Detail("editor.drop", "Drop files and pictures", "Editor", "Drag Markdown files (.md, .markdown, .mdown) or text notes (.txt) to open them, a folder to browse its contents, or PNG, JPEG, GIF, WebP and BMP pictures into the writing pane to choose whether to link or copy them. Other file types are refused with guidance; they are not opened or linked automatically.", "Choose a writable note. A new note asks where to save before picture insertion continues. A file or folder must exist locally.", CommandIds.ViewSplit, "Choose Split and drag the local item into the writing pane. Markdown or .txt opens in a tab, a folder appears as a directory tree, and a picture beside the Markdown file links immediately when dropped, selected or pasted with Ctrl+V; a picture from a subfolder or another location asks Link original or Copy image. Link uses its original path; Copy asks for a folder and filename and links the copy. Text notes remain editable and use the Markdown preview. Read any status message; unsupported and missing items are reported."),
        Detail("editor.practice", "Practice note and source-to-preview example", "Editor", "Try headings, bold text, a checklist, a quotation and a table in a small practice note. Source contains the writing marks; Reading preview shows their appearance.", "No account, connection or workspace is needed.", CommandIds.NewFile, "Choose Start here → Practise safely with a small note. Copy its example into a new document, choose Split and compare the writing with the preview. Try Undo, then Save as practice-note.md."),
        Panel("inspector.outline", "Document outline", "Read the heading hierarchy using the indentation and H1–H6 labels.", "Open a Markdown document containing # headings.", "Choose Inspector → Outline. Use Search headings to filter the list and check the result count. Select a heading to jump to it. Clear the field to see all headings."),
        Panel("inspector.links", "Search links in the document", "Find links in the active note by label or destination. Each row shows its destination and whether it is internal, external, or broken.", "Open a document containing Markdown links.", "Choose Inspector → Links. Type part of a label, path, or domain in Search label or destination. Select a result to jump to its source line. Clear the field to show all links."),
        Panel("inspector.info", "Document information", "See word count, estimated reading time and saved-document information. Statistics describe the current document text.", "Open or create a document.", "Choose Details in the inspector and review Document info. Write or edit text and allow analysis to refresh the counts."),
        Panel("inspector.tags", "Document tags", "Inspect tags extracted from supported document metadata. An empty list means no supported tags were found.", "Open a document with supported tag metadata.", "Choose Details in the inspector and review Tags. In Source, front matter such as tags: [writing, notes] between --- lines can supply tags. Review the refreshed list after editing."),
        Panel("inspector.history", "Inspector History section", "History shows local versions recorded when you save in Tern.", "Save your draft to a file first.", "Choose History in the Inspector and follow the on-screen steps. If no versions exist, edit and save the file in Tern, then return. Choose a dated version to compare, or use Open as copy to work in a separate unsaved tab."),
        Panel("inspector.brokenLinks", "Broken links and repair", "Find unresolved local links and choose an existing workspace target for an undoable repair. Save explicitly to write the repair.", "Open a workspace document with a broken local link.", "Choose Links in the inspector. Select the broken link, choose Repair selected link and the intended workspace target. Review the repair; Undo reverses it before saving."),
        new("library.recent", "Recent documents", "Library", "Recent history records file and URL references, not copies of document contents. Selecting a URL reuses its complete cached Markdown and assets when available; incomplete copies can retry downloads. Starting Tern does not automatically contact stored URLs. Remove a reference individually or clear recent history without deleting files.", "Available without a workspace. Open a saved document to populate recent history.", "", CommandIds.LibraryRecent, ["Choose Recent in the Library, or search Show Recent in the command palette.", "Select a file reference to open its file, or select a URL to reopen its cached editable unsaved copy or download it when needed. Use the row's remove action to forget one reference, or Clear recent history to forget all references.", "Open tabs and explicit workspace files remain independent. No physical document is deleted."]),
        Detail("library.shortcuts", "Collapse or expand Library shortcuts", "Library", "The Shortcuts row groups Recent, Search, All Files, Backlinks, Broken Links, and Tasks.", "Open the Library sidebar.", CommandIds.LibraryFiles, "Select Shortcuts at the bottom of the Library to collapse or expand the group independently of the folder tree."),
        Detail("library.files", "All Files", "Library", "Browse stacked physical folder and saved workspace trees. Expand descendants, use path tooltips, and select a root to target commands. Outside documents remain separate. Clearing recent history does not empty open roots.", "Open Folder browses an ordinary directory. Open Workspace restores a named persistent context. Neither is required to open individual files.", CommandIds.LibraryFiles, "Choose All Files. The tree shows supported Markdown/text notes and unexcluded folders, including empty folders; arbitrary binary files are not listed as notes. Use + Add to choose the selected root or outside all workspaces. Right-click a row for Create File, Create Folder or Create Workspace targeted to that row."),
        Detail("library.search", "Search results", "Library", "Revisit results from the latest workspace text search. This differs from filename Quick Open and from finding text inside one document.", "Open a workspace and run Search in Workspace. The panel is empty when there is no active search.", CommandIds.LibrarySearch, "Run Search in Workspace and enter a query. Choose Search in the Library to revisit its results, then select a result to open the file at the matching line."),
        Detail("library.backlinks", "Backlinks", "Library", "Find workspace documents that link to the active saved document. Backlinks describe incoming relationships, while the inspector Links tab describes links inside the active document.", "Open a workspace and a saved document within it.", CommandIds.LibraryBacklinks, "Choose Backlinks in the Library. Select a referring result to open the source document at its link. No results means the current workspace graph found no incoming links."),
        Detail("library.brokenLinks", "Broken Links", "Library", "List unresolved links across the workspace. The count badge signals issues to inspect; repairing a link requires reviewing its intended target.", "Open a workspace containing local links.", CommandIds.LibraryBrokenLinks, "Choose Broken Links in the Library and select a result to open its source. Inspect the target, then use the inspector Links tab for supported repair or edit the source manually."),
        Detail("library.tasks", "Tasks", "Library", "List unfinished Markdown task items found in workspace documents. The badge counts unfinished tasks; checking or unchecking a task changes document text only through an explicit edit.", "Open a workspace containing task-list markup such as - [ ] Write notes.", CommandIds.LibraryTasks, "Choose Tasks in the Library and wait for its scan. Select a task to open the source at that line. Use Toggle Task at Cursor to change completion, then save explicitly."),
        new("editor.lineEndings", "LF / CRLF / CR line endings", "Document format", "LF, CRLF and CR are line-break conventions. Existing files keep their text when opened; new notes default to Windows CRLF. Save, Save As and Save All preserve the selected LF, CRLF or CR convention. Encoding is separate.", "Open a writable document.", "", CommandIds.ChangeLineEnding, ["Open a writable document and click LF, CRLF or CR in the status bar.", "Choose LF (Unix / macOS), CRLF (Windows) or CR (classic Mac) to convert the open buffer.", "Review the buffer, then Save. All save actions preserve your selected line endings; character encoding remains separate."]),
        new("editor.encoding", "Encoding and BOM", "Document format", "Encoding determines how characters become bytes. BOM is an optional encoding marker. Preserve the detected format unless another tool requires a change.", "Open a document. Save or discard edits before reopening it with another decoding.", "", CommandIds.ChangeEncoding, ["Click the encoding label in the status bar or search Change Save Encoding.", "Choose the encoding required by the receiving tool. A conversion that would lose characters is refused.", "Save to write the selected encoding. Reopen with Encoding reads existing bytes differently; it is not the same operation."]),
        new("editor.scrollbars", "Pane boundaries and scrollbars", "Editor", "Drag the visible scrollbar thumb to move within a pane. Source and preview have independent bars; synchronized scrolling can link their movement.", "Open a document long enough to scroll.", "", CommandIds.ViewSplit, ["Choose Split so source and preview panes are visible.", "Drag either pane's scrollbar thumb or use the mouse wheel. The separator identifies the pane boundary.", "Use Settings → Reading and views → Synchronise scrolling in split view to link the panes, or turn it off for independent scrolling."]),
        Detail("search.case", "Match case", "Find and replace", "Require capital and lowercase letters to match exactly. With this on, Cat differs from cat.", "Open a document and its Find bar.", CommandIds.Find, "Enter the search text, enable Match case, and move through matches. Turn it off for a case-insensitive search."),
        Detail("search.word", "Whole word", "Find and replace", "Match complete words rather than text inside a longer word. Searching cat can exclude concatenate.", "Open a document and its Find bar.", CommandIds.Find, "Enter a word and enable Whole word. Review the highlighted matches before replacing any text."),
        Detail("search.regex", "Regular expression search", "Find and replace", "Use a regex pattern to describe matches instead of literal text. Invalid patterns report an error instead of replacing text.", "Open a document and its Find bar. Use literal search if you are unfamiliar with regular expressions.", CommandIds.Find, "Enable the regex option and enter a pattern. Inspect every match before replacing; turn regex off to search punctuation literally."),
        Detail("search.replaceAll", "Replace all matches", "Find and replace", "Replace every match in the current document using the active case, whole-word and regex options. This edits the buffer; save explicitly.", "Open a writable document and the Replace bar.", CommandIds.Replace, "Enter search and replacement text, review the match count and options, then choose Replace all. Undo reverses the edit; Save writes it to disk."),
        Detail("search.navigation", "Previous and next search match", "Find and replace", "Move between matches without changing text. Search navigation wraps through the document.", "Open Find and enter text that has matches.", CommandIds.Find, "Press Shift+F3 for the previous match or F3 for the next match. The arrow buttons perform the same actions. The match status reports the current result."),
        Detail("search.replaceOne", "Replace this match", "Find and replace", "Replace the selected search occurrence, leaving other matches for review. The active search options still apply.", "Open Replace in a writable document and find a match.", CommandIds.Replace, "Enter the replacement text, review the selected occurrence, then choose Replace. Move to the next result when ready; save explicitly."),
        Detail("editor.panes", "Resize writing panes", "Editor", "Drag pane separators to give the Library, source, preview or inspector more space. Source and preview remain separate areas in Split view.", "Open a document and show the panes you want to resize.", CommandIds.ViewSplit, "Move the pointer onto a pane separator and drag it. Keep enough width to read the source, preview and inspector comfortably."),
        Detail("editor.fencedCode", "Fenced code blocks", "Markdown", "Surround multiline code with triple backticks. A language name after the opening fence requests syntax highlighting when supported.", "Open a writable document in Source or Split.", CommandIds.ViewSplit, "On separate lines enter an opening triple-backtick fence, your code, and a closing triple-backtick fence. Add a language such as csharp after the opening fence, then review the preview."),
        Detail("recovery.review", "Review recovered work", "Recovery", "After an interrupted session, Tern can offer checkpoint text beside the current disk file. Recovery is separate from the session restore list.", "A recoverable checkpoint must already exist. Do not interrupt a working session just to try this feature.", CommandIds.Help, "If Review recovered work appears at startup, compare Current disk file with Recovered local edits. Choose Ask later if you need more time."),
        Detail("recovery.restore", "Restore recovered text as a copy", "Recovery", "Restore as unsaved copy opens checkpoint text separately, preserving the current disk document. Save recovered copy writes to a chosen separate destination.", "The recovery review dialog is open for an existing checkpoint.", CommandIds.Help, "Review the checkpoint, then choose Restore as unsaved copy or Save recovered copy. Inspect the result before saving. Discard checkpoint removes that recovery reference; Ask later postpones the decision."),
        Detail("conflict.merge", "Merge external changes", "File conflicts", "Compare the original base, your open edits and current disk edits before accepting a combined result. A merge is reviewed text, not an automatic overwrite.", "The same saved file changed externally while it had unsaved edits in Tern.", CommandIds.ReloadFromDisk, "When a conflict is reported, choose merge and select a conflicting region. Review the three text versions and the editable merged result before Accept merged text."),
        Detail("conflict.choices", "Keep mine, Take disk, Both and Original", "File conflicts", "For a selected merge region, Keep mine uses your text, Take disk uses the external text, Both includes both versions, and Original uses their common base.", "Open a merge review containing conflicting regions.", CommandIds.ReloadFromDisk, "Select a conflict, choose the desired region result, and review the full merged text. Cancel leaves the merge unaccepted. Save explicitly only when the reviewed result is correct."),
        Detail("history.compare", "Compare saved versions", "History", "Review the text of a recorded local version against the current document. History is local saved-text history, not an independent backup.", "Open a saved document with recorded versions.", CommandIds.ShowHistory, "Open Document Version History, select a version and compare its text before deciding whether to restore it."),
        Detail("history.restore", "Open a saved version as a copy", "History", "Open a historical version in a separate unsaved tab. The current draft and its saved file are preserved.", "Edit and save the file in Tern to record versions.", CommandIds.ShowHistory, "Open Inspector → History → Open version history. Choose a version by date and time, compare Saved version with Current draft, and choose Open as copy. Save the new tab to a separate path if you want to keep it."),
        Detail("library.missing", "Missing or inaccessible file", "Library", "A missing or inaccessible reference is marked so it can be distinguished from an available file. Removing the reference does not delete a physical file.", "A recent or workspace file reference is unavailable.", CommandIds.QuickOpen, "Check the displayed path and restore access or locate the file. Retry opening it, or remove the stale recent reference if it is no longer useful."),
        Detail("workspace.exclusions", "Workspace exclusions and .ternignore", "Workspace", "Exclude workspace paths using Settings → Workspaces and search → Workspace exclusion patterns, or a .ternignore file local to a workspace root. Both use gitignore-style patterns and do not delete documents.", "Review existing patterns before changing global settings or a workspace's .ternignore file.", CommandIds.Settings, "Add one reviewed pattern per line, such as drafts/, in Workspace exclusion patterns or .ternignore. Save the configuration, then safely close and reopen the affected workspace to apply the scan rules. Remove the pattern later to include those files again."),
        Detail("workspace.purpose", "Why use a workspace?", "Workspace", "A workspace groups an ordinary project folder for its explorer, search, links and tasks. It is optional: a single Markdown document can be opened, created and saved without any workspace.", "No workspace or open document is required to learn the difference.", CommandIds.OpenFolder, "Choose Open Folder when you already have a project folder. Choose Create Workspace for a new empty folder. Use standalone New document or Open Files for notes that do not need project-wide navigation."),
        Detail("workspace.standalone", "Open, create and save without a workspace", "Workspace", "Standalone documents remain ordinary files. They support Markdown editing, preview, Save and Save As without attaching their folders as projects.", "No workspace is required.", CommandIds.NewFile, "Choose New document or Open Files, write your text and Save to a filename and location. You may attach a workspace later for its explorer and project search; the file does not need conversion."),
        Detail("workspace.multiple", "Multiple workspaces", "Workspace", "Keep multiple project roots open and switch the active explorer/search/link graph between them. Document tabs and unsaved buffers remain open while you switch.", "Open at least one project folder; adding another existing folder creates another open root, not a duplicate of the same root.", CommandIds.OpenFolder, "Open another folder, then choose the desired root in the Library workspace selector. Browse that root's files. Close Workspace detaches one root; Close All Workspaces reviews all affected documents before detaching the roots."),
        Detail("workspace.switch", "Switch the active workspace", "Workspace", "The active root determines the Library tree and workspace search/link results. Switching does not close documents or discard unsaved edits. For nested roots, the nearest matching root owns a document.", "Open two or more workspace roots.", CommandIds.LibraryFiles, "Choose the workspace you want in the Library selector. Its explorer shows files belonging to that root, while the document tabs keep the files you opened from all roots."),
        Detail("workspace.newRoot", "Create a workspace folder", "Workspace", "Create a new empty project folder without overwriting an existing folder. A workspace remains an ordinary folder of files.", "Choose a parent location where you can create a new folder and enter an unused folder name.", CommandIds.CreateWorkspace, "Choose Create Workspace, select the parent location and enter the new folder name. After it opens, create a Markdown file there or use New document and Save into that folder. Use Open Folder for an existing project."),
        Detail("workspace.closeAllHelp", "Close all workspaces safely", "Workspace", "Detach all open project roots after reviewing unsaved changes across the affected groups. Standalone and unnamed documents remain separate; physical folders and files are preserved.", "At least one workspace is open. Save, Discard and Cancel decisions are completed before roots are detached.", CommandIds.CloseAllWorkspaces, "Choose Close All Workspaces and review each unsaved-document decision. Cancel keeps the close operation from completing; Save preserves the edits, while Discard abandons those edits. Reopen folders when you need their project navigation again."),
        Detail("file.renameLinks", "Review relative-link updates after rename", "File", "A saved-file rename can propose relative-link repairs. The file is already renamed when review appears. Open documents receive undoable edits that require Save; closed files are written only when their reviewed contents still match.", "Rename a saved document with affected supported relative links in its workspace. Naming an unsaved draft does not rename a physical file.", CommandIds.Rename, "In Review links after rename, inspect every file and its Before/After text. Choose Apply reviewed link updates only when correct, or Keep links unchanged to preserve the rename without repairing links. Review any conflict report; save modified open documents explicitly."),
        Detail("export.text", "Plain text export", "Export", "Export readable text with wrapped paragraphs, nested lists, untouched code indentation and Unicode to a separate .txt file. Small tables stay aligned; wide tables become labelled records. Numbered link references retain external, relative and section destinations without stretching table columns. Plain text cannot retain fonts, colours or images. The source document is preserved.", "Open a document.", CommandIds.ExportAs, "Choose File → Export As…, choose Plain text in Format, browse to a separate output file and choose Export. Review the generated text using Open file beside the completion status."),
        Detail("reset.history", "Reset recent history", "Reset", "Clear stored recent and pinned references. Open document tabs, workspace contents and physical files are independent.", "No document is required.", CommandIds.Reset, "Open Reset Tern, select Recent history and review the other selected categories before choosing Reset selected application data."),
        Detail("reset.preferences", "Reset preferences and keyboard shortcuts", "Reset", "Restore default preferences and command bindings. This changes the application configuration rather than document contents.", "No document is required. Note any custom shortcuts you want to recreate.", CommandIds.Reset, "Open Reset Tern, select Preferences and keyboard shortcuts, review the scope, then reset the selected categories."),
        Detail("reset.session", "Reset session restore list", "Reset", "Clear the list used to reopen saved tabs and the workspace on startup. Open drafts and recovery copies are preserved.", "No document is required.", CommandIds.Reset, "Open Reset Tern and select Session restore list. Review the scope before resetting selected application data."),
        Detail("reset.remoteCache", "Clear cached online documents and assets", "Reset", "Remove managed online Markdown snapshots and downloaded dependencies from the remote cache. User downloads, attachments, drafts, recovery copies and AI credentials remain separate.", "Close cached online tabs first. Save a portable local copy when you want to keep one.", CommandIds.Reset, "Open Reset Tern, select Cached online documents and assets, review the scope and choose Reset selected. Reopening an uncached URL needs a connection again."),
        Detail("reset.index", "Reset search indexes", "Reset", "Remove rebuildable workspace search-index data. This does not remove source files or folders.", "Close the workspace first.", CommandIds.Reset, "Close the workspace, open Reset Tern and select Search indexes. Reopen the workspace afterward so its index can be rebuilt."),
        new("ai.workflow", "Work with or without AI", "AI Connections", "AI can draft, rewrite and explain Markdown. Use Write with AI to generate a suggestion, then review and apply the changes you want. The guide answers general questions without attaching your note. AI can be wrong and cloud services may charge.", "Cloud APIs need API access. Local Ollama needs a running server and model. GitHub Copilot uses its saved CLI connection. MCP supplies tools. Opening a window or selecting a connection sends nothing.", "", CommandIds.AIConnections,
            ["Choose Edit → Settings → AI connections, then Manage AI connections. Choose a service, Configure connection, enter a name, model and key, then Continue to validation. Validate connection sends a fixed test message; Save connection stores the settings securely.",
             "All saved API, GitHub Copilot and MCP connections appear in the toolbar. Share text through Write with AI using an API or Copilot model. Check the Local or Remote destination and the last check in this session. Use Open MCP tools for manually reviewed tool calls.",
             "Press Ctrl+Shift+Space in an editable note. For an empty note, describe what you want to draft in the larger instruction box. With text selected in Source, choose Rewrite, Summarize, Explain, Extract tasks, or Proofread to fill in an editable instruction.",
             "Without a selection, you can share the entire note or only your instruction. With a selection, you can share Selected text or only your instruction; clear the selection to share the entire note. Check the connection, then choose Generate for review.",
             "In Review AI suggestion, compare Original and Result. For selected text, Apply changes replaces only that selection. A summary, explanation, or task list made from the entire note is inserted and keeps the note. Back sits in the bottom row beside Copy result. Use it to revise your instruction and generate again.",
             "Compare the complete BEFORE and AFTER Markdown. The review explains the steps and changed-section count; narrow screens stack the comparison. Back returns to your instruction. Copy result copies the full suggestion. Apply uses all proposed changes. Close or Escape discards the suggestion. If the note changed, start again with the latest version. Applied changes can be undone together. Save the draft when ready."]),
        Detail("help.messages", "What Tern's messages mean", "Getting help", "Information (i) is something you may want to know. Success (✓) means what you asked for is done. Warning (!) means Tern needs your attention, so check the message and follow its next step. Error (×) means something did not work. Read the message, fix what it names and try again.", "No document is required.", CommandIds.Help, "Look at the message box or the status bar at the bottom of Tern. Message boxes and the status bar show each level with a color and a symbol. Warnings and errors stay until a new message replaces them. Select the status bar message to see earlier messages in Activity."),
        Detail("performance.largeNotes", "Large notes and background updates", "Files and performance", "Source view defers preview work. Link information and searches may update briefly after you finish typing. Large merges can show broader conflicts to keep memory bounded.", "Open a local note or workspace. The 64 MiB file-opening ceiling is a safety limit, not a speed guarantee.", CommandIds.ViewSource, "Choose Source while editing a large note, then Split or Reading when you need its preview. Let workspace preparation finish before searching. Review any preview truncation notice. Open from URL downloads up to four dependencies at a time with a two-minute overall deadline; retry or save a local copy if the connection fails. Cached assets stay on disk, and unused superseded snapshots expire after seven days while open snapshots remain protected."),
        Detail("ai.markdownActions", "Markdown AI actions", "AI Connections", "Improve, summarize, explain or proofread text, or turn it into a checklist.", "Open an editable note with a saved writing model.", CommandIds.AskAI, "Select text and choose Edit → Write with AI to see prompt starters. Edit the suggested instruction, check the scope and connection, then generate. Results for selected text replace that selection after review. Explanations, summaries and action items for an entire note are inserted. Copy is always available."),
        Detail("ai.workspace", "Explore your notes", "AI Connections", "Ask in everyday language and get a short AI answer from your own notes, with a link to every source.", "Add an AI connection and open a workspace with locally available notes. If no AI exists, Tern opens AI Connections first.", CommandIds.AskKnowledge, "Choose Edit → Explore your notes. Type a question naturally or choose a suggestion, replace any [bracket] word and press Find my notes. AI interprets the question. A search with no matches may have missed notes that use different words; it does not mean every note was read. Keep the notes that fit and press Get my answer. AI reads all the notes you keep ticked, in parts when needed, up to 1,000,000 characters per question. It names anything not read. Simple one-fact questions may start with the best sections, then read the full ticked text if needed. Version-range questions cover the full range. Then choose one: Copy for email, Save as PDF, Add to my note or Print. Tern prepares and checks one complete report before it is ready to share. Its executive summary comes first, followed by detailed findings, exact source evidence and a final review record. Copy for email builds a summary on this computer from your checked report; PDF, note and print keep the full report. Switching formats reuses the same checked result without asking AI again. Editing the report or changing its sources requires a new check. Closing keeps unfinished work without sending anything. Done finishes the task; Ask a new question starts again. Change AI from the top AI button."),
        Detail("ai.relatedNotes", "Suggest related documents", "AI Connections", "Find related notes in the current workspace and choose which Markdown links to insert.", "Open a saved, editable note in a workspace and save a writing model.", CommandIds.AIConnections, "Open Inspector → Links → Suggest related documents. Enter a topic, find passages, and review the request before sending. Read the reasons, select the notes to link, and choose Insert selected links. Undo removes the inserted links together."),
        Detail("ai.openaiCompatible", "OpenAI-compatible AI connection", "AI Connections", "Use a compatible non-streaming text chat-completions endpoint. Provider-specific tools, image inputs and authentication variants are outside this adapter.", "Obtain an HTTPS cloud endpoint or run a compatible local server. You need its model name and any required API key.", CommandIds.AIConnections, "Choose the OpenAI-compatible protocol, enter the full chat-completions endpoint and model, then Continue to validation. Validate connection sends a fixed test message; read the result and Save connection. Use Try your own message (optional) for a separate reviewed question."),
        Detail("ai.guidedSetup", "Guided AI connection setup", "AI Connections", "Follow three stages: Choose service, Configure connection, and Validate and save. Back keeps entered values. Opening setup, navigating and saving make no network request; Validate connection deliberately contacts the selected model.", "Have access to the selected service API or a running local model server. Website subscriptions do not necessarily include API access.", CommandIds.AIConnections, "Use the AI service menu for OpenAI API, Anthropic API (Claude), Ollama (local), DeepSeek API, Custom AI Connection, GitHub Copilot or MCP server. The selection enables the appropriate fields and setup. Create connection starts a new profile. Selecting any saved connection stays on Choose service and updates the AI service menu; choose Configure connection to open its settings, or Delete connection to remove it after confirmation. Setup guide opens official documentation for the selected service, including GitHub Copilot authentication and the MCP 2025-11-25 Streamable HTTP specification. For an API, enter a connection name, exact model ID and required key; use Advanced only for custom addresses. Choose Continue to validation, review the destination, and choose Validate connection to send the fixed test message. Read success or the error, then Save connection. Saving an untested connection is allowed but does not establish that it works. Expand Try your own message (optional) only when you want to review and send your own text."),
        Detail("ai.sendCharacters", "Characters to send at one time", "AI Connections", "Each AI connection saves how many characters Tern may send in one request. New connections start at 256,000. Older connections without a saved value receive 256,000 once. Connections with a saved value keep it. Choose a whole number from 8,000 to 1,000,000. This range checks the field; it does not measure what your service accepts.", "Open the AI connection you want to change. MCP servers provide tools and have no character field.", CommandIds.AIConnections, "Under Model, enter Characters to send at one time, then save. An empty or invalid value shows a red message and blocks saving. Writing, Explore, Help, Learn Tern and connection test messages use this saved value. It counts all instruction and data text, including Tern's rules and connection-test instructions. The value is a total, not an allowance for your text alone. Explore reads notes in parts when needed. If AI refuses a size, Explore halves the request size, down to 8,000 characters, and suggests a lower value without changing your saved value. Write with AI keeps your text together and warns before Send: select less or raise the value. Help shares the global AI choice."),
        Detail("ai.freshRequests", "Every AI request starts fresh", "AI Connections", "Earlier questions, replies and conversation transcripts are not sent with your next request. This applies to AI requests from Explore, writing, Help, Learn Tern, report preparation, connection tests and retries. Copy for email works locally from the checked report and makes no AI request.", "Choose a saved AI model. Check the current request and what material it needs.", CommandIds.AskKnowledge, "Each step receives Tern's rules, your current request and the current job's notes, extracted facts or edited draft needed for that step. The rules are kept separate from source material. Restoring unfinished work on your computer does not resume a provider conversation or send automatically. Include needed context in your current question. The service's own retention policy still applies."),
        Detail("ai.completeReport", "Review and share a complete report", "AI Connections", "One report supplies every sharing format. An executive summary comes first, followed by detailed findings, exact source evidence and final actions, limitations and a blank decision or review record.", "Get an answer in Explore your notes. Keep the current source notes available.", CommandIds.AskKnowledge, "Choose a sharing format. Tern prepares and checks the complete report before it is ready. Read the report and check its bold keywords, figures, quotations and source headings and line locations. Facts, calculations, targets and recommendations stay distinct. Choose Use this checked report, then Preview report to read the formatted full report. Edit more report details opens the extra fields. If you edit the report, press Check report; this checks the edits without exporting. Then tick I reviewed this report. A report edit requires a new check; changing only the output format reuses your checked result. Check its conclusions yourself too. If it finds problems, the screen gives a short explanation. Expand What needs checking for more detail, or choose Ask AI to correct these issues to request help. This sends the current report, issues and notes in a fresh request. Tern checks quotations, evidence and the whole proposed report again. A new draft needs your review before sharing; nothing exports automatically. A failed or out-of-date correction keeps your wording and issues. After editing the report yourself, check it again before requesting correction. Copy for email builds a professional executive summary from this checked report on this computer, without another AI request. Review and paste it into your email app; no file is attached. PDF and Print use the full report. Once the report is ready, saving another format does not reread the notes or ask AI again. Add to my note keeps the full Markdown structure, tables, quotations and source references. The final record leaves space for signatures and a date; blank does not mean approved. If AI stops before finishing a large report, Tern completes smaller independent sections and combines their checked evidence. Each request starts fresh; earlier chat is not continued."),
        Detail("ai.unfinishedTask", "Return to unfinished Explore work", "AI Connections", "Reopening Explore returns to your last stage and keeps your inputs and report edits. It never contacts AI just because it opens.", "Unfinished work belongs to its workspace. Normal workspaces keep a protected local checkpoint. Private workspaces keep it only while Tern is open.", CommandIds.AskKnowledge, "Close the window when you want to continue later. Copying or exporting leaves the task available for other formats. Choose Done after completing all wanted outputs. Tern automatically removes the task checkpoint and releases its cached notes, report and prepared PDF; saved outputs are kept. Ask a new question also clears the previous task. Closing the window releases its local cache while retaining unfinished work for later. If a step was interrupted, choose Retry. If notes changed or disappeared, choose Refresh notes before reusing the evidence; your wording is kept. Preparing or rechecking requires an available AI connection; checked local outputs remain available offline while their sources remain valid. A Private workspace cannot restore a task after Tern closes."),
        Detail("ai.accountAccess", "ChatGPT accounts and API access", "AI Connections", "An OpenAI API connection is separate from signing in to ChatGPT on the web. Tern does not import ChatGPT conversations, subscriptions or browser credentials. The service's API account controls model access and charges.", "Obtain API access, credentials and a model identifier from the service you intend to use.", CommandIds.AIConnections, "Select OpenAI API, DeepSeek API or Custom AI Connection. For a custom connection, enter the complete API endpoint and a model available to that API account. Start with a small non-sensitive reviewed message; do not paste website passwords or session cookies."),
        Detail("ai.claude", "Claude native Anthropic API", "AI Connections", "Use Claude through Anthropic's native Messages API. A Claude consumer subscription does not supply API credentials. This adapter sends one reviewed text message without tools or automatic document access.", "Obtain an Anthropic API key and a Claude model identifier available to that API account.", CommandIds.AIConnections, "Choose Anthropic API (Claude) in the service presets. Confirm the preset Messages API endpoint, enter the available model ID and API key, then Continue to validation. Validate connection sends a fixed test message; read its result and Save connection. Use Try your own message (optional) for a separate reviewed question."),
        new("ai.mcp", "MCP server connections and tools", "AI Connections", "Save a manual tool-server connection, validate it by discovering tools, and review each tool call separately. Supported: MCP 2025-11-25 Streamable HTTP with JSON or request-scoped SSE. MCP does not provide an AI model; OAuth and stdio are unsupported.", "Obtain a compatible HTTP MCP endpoint and any required bearer token from its administrator. Tern works only with servers that accept MCP 2025-11-25. A server that supports only a newer version will not connect.", "", CommandIds.AIConnections,
        ["Open AI Connections and choose MCP server in the AI service menu, then Configure connection. Selecting a saved server stays on Choose service until Configure connection is clicked. Setup guide opens the official MCP 2025-11-25 Streamable HTTP specification. Opening or loading saved settings sends nothing and attaches no document or filesystem roots.", "In Configure, select a saved connection or enter its name, full HTTPS endpoint (HTTP allowed on loopback) and optional bearer token. Ask the administrator for MCP 2025-11-25 compatibility; OAuth login and stdio processes are not supported.", "Continue to Validate and save. Connect and discover tools initializes the server and lists tools; it does not run one. Read any endpoint, authentication or compatibility error before trying again. Save connection stores the settings and protects the token in Windows Credential Manager.", "Select the saved MCP connection through the AI entry and choose Open MCP tools. The saved server is selected without a request. Choose Connect and discover tools; in Review tools, select a discovered tool and read its description and input schema as untrusted information. Enter the exact JSON object arguments you authorize. A tool may change server files or accounts, send messages or incur costs.", "Review the server, tool and arguments before checking consent and choosing Run reviewed tool. Cancel stops waiting but cannot undo effects already performed. Results are untrusted JSON, not document edits; calls are never automatically retried. Reopen saved settings later, or use Delete saved connection to remove them."]),
        new("ai.copilot", "Configure and write with GitHub Copilot", "AI Connections", "Save a Copilot CLI connection and use it from the main toolbar to write or answer guide questions. The writing panel sends the active note only after Generate; the separate question tool sends only reviewed text. Ordinary writing works without Copilot.", "You need GitHub Copilot access, installed native copilot.exe, and a personal-account-owned fine-grained GitHub token with the Copilot Requests account permission. A website password, classic token or OpenAI key is not a substitute.", "", CommandIds.AIConnections,
        ["Choose Edit → Settings → AI connections → Manage AI connections, then select GitHub Copilot in the AI service menu and Configure connection. Selecting a saved Copilot connection stays on Choose service until Configure connection is clicked. Setup guide opens GitHub's official CLI authentication instructions. Opening or loading saved settings sends nothing.", "In Configure, select a saved connection or enter a connection name and your fine-grained GitHub token owned by your personal account with the Copilot Requests account permission. Copilot Chat permission is not required. Keep Model set to auto for a first test; use Advanced to check the trusted native copilot.exe location.", "Continue to Validate and save. Validate connection sends the fixed test message through the selected CLI and model, without attaching a document. Provider usage may apply. Read success or the error; check token permission, Copilot entitlement, model and CLI path when validation fails.", "Choose Save connection to keep metadata and store the token in Windows Credential Manager. The saved connection appears through the AI entry and in the shared saved-connections list. Select it to modify settings or choose Delete connection after review. You can also use New connection and Delete saved connection.", "Choose the saved Copilot connection through the AI entry and Write with AI to edit the active note. Check the text scope and connection before choosing Generate for review. Validation sends a fixed test before generation unless an unchanged connection passed within the last 30 seconds. The approved text and instruction are still checked for every generation. Apply the changes you want; Undo restores the draft. The note and instruction must fit this connection's Characters to send at one time value; @mentions and CLI commands are not accepted. For a separate question in Try connection, review the text, check consent, then Send reviewed text; that answer is not applied automatically.", "Cancel request stops waiting but cannot recall text already received. Editing the CLI destination clears a restored token so you can review and enter it again. Live account and model availability remain user-specific and unverified by this guide."],
        AdvancedDetails: "The adapter runs native copilot.exe with a reviewed flag set for version 1.0.95, isolated configuration and an empty working directory. It disables built-in tools, IDE context and automatic workspace attachments. Explicitly saved tokens use Windows Credential Manager; unsaved tokens stay in memory. The token is passed through the child process environment rather than arguments or metadata JSON. This is not an operating-system sandbox. New CLI versions and live provider/account compatibility require separate validation."),
        Detail("ai.ollama", "Native Ollama AI connection", "AI Connections", "Use the Ollama text-chat protocol for a running local model server. This is a separate adapter from the OpenAI-compatible endpoint.", "Start Ollama and make the requested model available on that server.", CommandIds.AIConnections, "Choose native Ollama, enter its chat endpoint and model, then Continue to validation. Validate connection sends a fixed test message; read the result and Save connection. Use Try your own message (optional) for separately reviewed text."),
        Detail("ai.profiles", "Save and remove an AI connection", "AI Connections", "Keep named API, MCP and Copilot settings for reuse. Secret keys are stored separately in Windows Credential Manager rather than metadata JSON. Saving does not contact a provider.", "Configure a connection on Windows. Validation contacts the selected service only when requested.", CommandIds.AIConnections, "Enter a connection name during Configure and continue to Validate and save. Validate connection tests API generation with a fixed message; Save connection or Save changes stores settings without sending. Selecting any saved API, Copilot or MCP connection in the shared list stays on Choose service. Choose Configure connection to modify its settings, or Delete connection and confirm removal. Create connection starts a fresh setup using the AI service menu. All saved connections appear through the AI entry; MCP uses Open MCP tools rather than note generation."),
        Detail("ai.review", "Review AI content and cancel requests", "AI Connections", "In Try your own message (optional), Tern's instructions and the manually pasted message are sent after consent; no note is attached. Validate connection uses a separate fixed test message. Changing the endpoint, model, provider, key or message invalidates that review. Cancel cannot recall data already received by a service.", "Configure a compatible AI connection. Do not paste private text you do not want that service to receive.", CommandIds.AIConnections, "On Validate and save, expand Try your own message (optional). Read the endpoint and exact message, check consent, then Send request. Use Cancel request to stop waiting; review any response before copying it into a document."),
    ];

    private static FeatureHelp Panel(string id, string name, string description, string prerequisite, string action) =>
        new(id, name, "Inspector", description, prerequisite, "", CommandIds.ToggleRightPanel,
        ["Open the document inspector using View → Inspector or its current command-palette entry.", prerequisite, action, "Select a different inspector section or close the panel when finished. Viewing information does not save or modify the document."]);

    private static FeatureHelp Detail(string id, string name, string category, string description, string prerequisite, string command, string action) =>
        new(id, name, category, description, prerequisite, "", command,
        [$"Before you start: {prerequisite} This guide never performs the action automatically.", action, "Review the result and any confirmation before saving or replacing data. You can skip, replay or exit this lesson at any time."]);
}
